body.script:
// Export to lossless SVG
function exportSVG(containerId, filename) {
    const container = document.getElementById(containerId);
    const svgElement = container.querySelector('svg');

    if (!svgElement) {
        alert("Diagram is still loading. Please try again later.");
        return;
    }

    // Deep clone the SVG to avoid mutating the visible DOM
    const svgClone = svgElement.cloneNode(true);
    svgClone.setAttribute("xmlns", "http://www.w3.org/2000/svg");

    // Apply inline style to force transparent background to be visible as #121212 when opened in blank tab
    svgClone.style.backgroundColor = "#121212";
    svgClone.style.padding = "20px";

    const serializer = new XMLSerializer();
    const svgString = serializer.serializeToString(svgClone);
    const blob = new Blob([svgString], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    link.click();

    // Garbage collection
    setTimeout(() => URL.revokeObjectURL(url), 100);
}

// Export to crisp 2x supersampled PNG
function exportPNG(containerId, filename) {
    const container = document.getElementById(containerId);
    const svgElement = container.querySelector('svg');

    if (!svgElement) {
        alert("Diagram is still loading. Please try again later.");
        return;
    }

    const serializer = new XMLSerializer();
    const svgString = serializer.serializeToString(svgElement);
    const blob = new Blob([svgString], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(blob);

    const img = new Image();
    img.onload = function() {
        const canvas = document.createElement("canvas");
        const bbox = svgElement.getBoundingClientRect();

        // Fallback dimensions in case bounding box is not loaded properly
        let width = bbox.width;
        let height = bbox.height;
        if (!width || !height) {
            width = parseFloat(svgElement.getAttribute("width")) || 900;
            height = parseFloat(svgElement.getAttribute("height")) || 700;
        }

        // 2x Supersampling for crisp text and lines
        canvas.width = width * 2;
        canvas.height = height * 2;

        const ctx = canvas.getContext("2d");

        // Fill background with matching solid dark theme color
        ctx.fillStyle = "#121212";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Scale rendering context by 2x to draw the high-res SVG
        ctx.scale(2, 2);
        ctx.drawImage(img, 0, 0, width, height);

        // Trigger download
        const link = document.createElement("a");
        link.href = canvas.toDataURL("image/png");
        link.download = filename;
        link.click();

        // Garbage collection
        setTimeout(() => URL.revokeObjectURL(url), 100);
    };
    img.src = url;
}
